import{_ as t,H as o,f as a,i as r}from"./chunks/framework.CBmkDW73.js";const g=JSON.parse('{"title":"debug","description":"","frontmatter":{},"headers":[],"relativePath":"zh/skills/debug.md","filePath":"zh/skills/debug.md"}'),l={name:"zh/skills/debug.md"};function s(d,e,i,n,u,_){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="debug" tabindex="-1">debug <a class="header-anchor" href="#debug" aria-label="Permalink to &quot;debug&quot;">​</a></h1><p><code>debug</code> 技能用于以确定性根因定位替代猜测式试错，隔离并修复故障、回归与失败测试。</p><p>在 <code>topology=multi-module</code> 场景下，先在各参与仓库内只读排查，仅在任务登记的所属模块仓库内修复问题，并延后关联提交直到协调者集成验收通过（见<a href="./multi-module.html">多模块协议</a>）。</p><h2 id="调试流程" tabindex="-1">调试流程 <a class="header-anchor" href="#调试流程" aria-label="Permalink to &quot;调试流程&quot;">​</a></h2><ol><li><strong>稳定复现</strong>：建立最小化可确定重现的用例。无法复现则不贸然修改。</li><li><strong>根因定位</strong>：持续追问“为什么”，直到单个根因能够解释<strong>全部</strong>现象。每次只改变一个变量；若连续 3 次假设失败，停下来重新从头通读代码与完整报错。</li><li><strong>TDD 修复</strong>：先写失败的回归测试（RED），从根因处修复使之通过（GREEN），并运行完整测试套件确认无回归。</li></ol><p>完成标准 = 确定性复现 + 先红后绿的回归测试 + 明确根因说明 + 测试全绿。</p>',6)])])}const p=t(l,[["render",s]]);export{g as __pageData,p as default};
